#pragma once
static void checkUserHydrazine(App& app,const std::string& dir){
    auto path=dir+"/user-hydrazine-input.r62doc";if(GetFileAttributesW(W(path).c_str())==INVALID_FILE_ATTRIBUTES)return;
    auto require=[](bool ok,const std::string& why){if(!ok)throw std::runtime_error(why);};auto& s=app.s;s.cancel();s.history.clear();require(s.open(path).ok(),"open user's live hydrazine reaction copy");auto reroute=[&](std::vector<ObjectId> ids){Document routing=s.doc;for(auto id:ids)routing.removeObject(ObjectRef(ObjectKind::Arrow,id));for(auto id:ids){arrows::ArrowParams p;bool ok=false;arrows::readArrow(s.doc,id,&p,&ok);require(ok,"read actual user arrow for updated routing");arrows::mechanismAnchorPoint(s.doc,p.electronSource,&p.begin);arrows::mechanismAnchorPoint(s.doc,p.electronTarget,&p.end);if(p.presetId==57)p.head.sides=arrows::HeadSides::Right;p.route.clear();arrows::routeMechanism(routing,p);arrows::clearMechanismLabels(routing,p);require(arrows::writeArrow(s.doc,id,p,.6).ok(),"reroute actual user arrow without moving atoms");}};reroute({31,32,33});auto before=s.doc.digest();auto count=s.doc.stats().aliveAtoms;
    s.selected={ObjectRef(ObjectKind::Arrow,31),ObjectRef(ObjectKind::Arrow,32),ObjectRef(ObjectKind::Arrow,33)};app.generateMechanismStep();require(s.doc.digest()==before&&s.doc.stats().aliveAtoms==count,"contradictory carbonyl arrows cannot create hypervalent carbon");
    s.selected={ObjectRef(ObjectKind::Arrow,31),ObjectRef(ObjectKind::Arrow,32)};app.generateMechanismStep();require(s.doc.stats().aliveAtoms==count+20,"actual hydrazine addition creates all twenty product atoms");
    std::map<ObjectId,ObjectId> made;for(auto ref:s.selected)if(ref.kind==ObjectKind::Atom)made[studio_mechanism_products::sourceAtom(s.doc,ref.id)]=ref.id;auto carbon=made.at(209),oxygen=made.at(211),nitrogen=made.at(220);require(s.doc.atoms().alive(oxygen)->semantics.charge==-1&&s.doc.atoms().alive(nitrogen)->semantics.charge==1&&!s.doc.atoms().alive(carbon)->semantics.charge,"actual hydrazine addition has O minus, N plus and neutral tetrahedral carbon");require(s.doc.bonds().alive(s.doc.bondBetween(carbon,oxygen))->order==BondOrder::Single&&s.doc.bondBetween(carbon,nitrogen)!=kInvalidObjectId,"actual hydrazine C--N forms and carbonyl reduces");
    std::vector<ObjectRef> excerpt=s.selected;std::set<ObjectId> source;for(ObjectId id=201;id<=218;++id){source.insert(id);excerpt.emplace_back(ObjectKind::Atom,id);}for(ObjectId id:{220,221}){source.insert(id);excerpt.emplace_back(ObjectKind::Atom,id);}for(const auto& b:s.doc.bonds().records())if(b.isAlive()&&source.count(b.beginAtom)&&source.count(b.endAtom))excerpt.emplace_back(ObjectKind::Bond,b.id);excerpt.emplace_back(ObjectKind::Arrow,31);excerpt.emplace_back(ObjectKind::Arrow,32);
    Session clean;require(studioio::append(s.doc,clean.doc,excerpt,Vec2(),nullptr).ok(),"extract corrected user reaction without old malformed products");require(clean.save(dir+"/hydrazine-corrected-reaction.cdxml",true).ok(),"save corrected actual reaction");s.doc=clean.doc;s.selected.clear();s.refresh();s.fit();app.invalidate();app.screenshot(dir+"/hydrazine-corrected-reaction.png");
    s.history.clear();require(s.open(path).ok(),"reopen actual fishhook source");reroute({21,22,23});arrows::ArrowParams departure;bool departureValid=false;arrows::readArrow(s.doc,22,&departure,&departureValid);Vec2 departureCenter,receivingCenter;arrows::mechanismAnchorPoint(s.doc,departure.electronSource,&departureCenter);arrows::mechanismAnchorPoint(s.doc,departure.electronTarget,&receivingCenter);require(departureValid&&dot(departure.begin-departureCenter,receivingCenter-departureCenter)>0,"actual wedge fishhook exits on the target-facing side without crossing the wedge");integration::RingGeometry wedgeGeometry(s.doc);auto wedge=wedgeGeometry.build(*s.doc.bonds().alive(109));for(const auto& shape:wedge.shapes)if(shape.kind==bonds::BondShapeKind::FilledPolygon){const auto& polygon=shape.outline;for(auto point:arrows::routedPoints(departure)){bool inside=false;for(size_t i=0,j=polygon.size()-1;i<polygon.size();j=i++){auto a=polygon[i],b=polygon[j];if((a.y>point.y)!=(b.y>point.y)&&point.x<(b.x-a.x)*(point.y-a.y)/(b.y-a.y)+a.x)inside=!inside;}require(!inside,"actual fishhook shaft never re-enters the filled wedge near its source");}}arrows::ArrowParams duplicated;bool valid=false;arrows::readArrow(s.doc,21,&duplicated,&valid);require(valid,"read active radical arrow");ObjectId duplicate;require(arrows::addArrow(s.doc,duplicated,.6,&duplicate).ok(),"add synthetic duplicate hook regression");before=s.doc.digest();count=s.doc.stats().aliveAtoms;s.selected={ObjectRef(ObjectKind::Arrow,21),ObjectRef(ObjectKind::Arrow,22),ObjectRef(ObjectKind::Arrow,23),ObjectRef(ObjectKind::Arrow,duplicate)};app.generateMechanismStep();require(s.doc.digest()==before,"overlaid repeated radical arrows never double-spend an electron");
    s.doc.removeObject(ObjectRef(ObjectKind::Arrow,duplicate));s.selected={ObjectRef(ObjectKind::Arrow,21),ObjectRef(ObjectKind::Arrow,22),ObjectRef(ObjectKind::Arrow,23)};app.generateMechanismStep();require(s.doc.stats().aliveAtoms==count+20,"actual radical fragmentation creates complete products");made.clear();for(auto ref:s.selected)if(ref.kind==ObjectKind::Atom)made[studio_mechanism_products::sourceAtom(s.doc,ref.id)]=ref.id;auto acyl=made.at(124),alkoxy=made.at(118),alkyl=made.at(110);require(!s.doc.atoms().alive(acyl)->semantics.charge&&!s.doc.atoms().alive(acyl)->semantics.radical&&!s.doc.atoms().alive(alkoxy)->semantics.charge&&!s.doc.atoms().alive(alkoxy)->semantics.radical&&s.doc.atoms().alive(alkyl)->semantics.radical==uint8_t(Radical::Doublet),"actual Barton-type fragmentation produces neutral carbonyl and ring carbon radical");
    {auto dots=arrows::mechanismRadicalPoints(s.doc,alkyl);auto center=s.doc.atoms().alive(alkyl)->position;Vec2 outward;for(auto bid:s.doc.incidentBonds(alkyl)){auto b=s.doc.bonds().alive(bid);auto v=s.doc.atoms().alive(b->beginAtom==alkyl?b->endAtom:b->beginAtom)->position-center;if(length(v)>1e-8)outward=outward-v*(1./length(v));}require(dots.size()==1&&length(outward)>1e-8&&dot(dots.front()-center,outward)/(length(dots.front()-center)*length(outward))>.999999,"new ring-carbon radical dot follows the exterior bond bisector");}
    require(s.doc.bonds().alive(s.doc.bondBetween(acyl,alkoxy))->order==BondOrder::Double&&s.doc.bondBetween(alkoxy,alkyl)==kInvalidObjectId,"actual radical fragmentation has correct double bond and cleavage");excerpt=s.selected;source.clear();for(ObjectId id=108;id<=127;++id){source.insert(id);excerpt.emplace_back(ObjectKind::Atom,id);}for(const auto& b:s.doc.bonds().records())if(b.isAlive()&&source.count(b.beginAtom)&&source.count(b.endAtom))excerpt.emplace_back(ObjectKind::Bond,b.id);for(ObjectId id:{21,22,23})excerpt.emplace_back(ObjectKind::Arrow,id);Session radicalExample;require(studioio::append(s.doc,radicalExample.doc,excerpt,Vec2(),nullptr).ok()&&radicalExample.save(dir+"/actual-radical-fragmentation.cdxml",true).ok(),"save corrected actual fishhook reaction");s.doc=radicalExample.doc;s.selected.clear();s.refresh();s.fit();app.invalidate();app.screenshot(dir+"/actual-radical-fragmentation.png");
}
